def sum5 : Finset (ZMod 5) := Finset.image2 (fun x y : ZMod 5 => x + y) ({1, 4} : Finset (ZMod 5)) ({1, 4} : Finset (ZMod 5))
def sum8 : Finset (ZMod 8) := Finset.image2 (fun x y : ZMod 8 => x + y) ({1, 6} : Finset (ZMod 8)) ({1, 6} : Finset (ZMod 8))
def check5 : Bool := decide (sum5 = ({0, 2, 3} : Finset (ZMod 5)) ∧ Disjoint ({1, 4} : Finset (ZMod 5)) sum5)
def check8 : Bool := decide (sum8 = ({2, 4, 7} : Finset (ZMod 8)) ∧ Disjoint ({1, 6} : Finset (ZMod 8)) sum8)
def check_L1_fragment : Bool := check5 && check8

